{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C22", "C23", "C26", "C30"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C22", "C23", "C26", "C30"],
  "claims": [
    {
      "claim": "The query is rifampicin, a rifamycin ansamycin. L3 oral-exposure records for rifamycin analogs show substantial systemic exposure after oral dosing: C22/C23 (M04; source context matches rifampicin) report AUC0-24h 40.8 mg·h/L and Cmax 9.0 mg/L after ~10 mg/kg oral daily, and C30/C26 (M03 rifabutin) report Cmax 188 ng/mL and AUC0-tau 8.1 µg·h/mL. This supports F >= 20%.",
      "card_ids": ["C22", "C23", "C26", "C30"]
    },
    {
      "claim": "C25/C31 report midazolam Tmax during rifaximin coadministration rather than rifaximin exposure, and M02/M05 records are structurally unrelated; none provides affirmative evidence of F < 20% for the query or a close analog.",
      "card_ids": ["C25", "C31", "C24", "C27", "C28", "C29", "C32", "C33"]
    },
    {
      "claim": "The low physicochemical prior is descriptor-based and, per protocol, cannot by itself establish F < 20%; no transferable measured low-F outcome is present.",
      "card_ids": ["C22", "C23", "C26", "C30"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C22", "C23", "C26", "C30"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C25", "C31", "C24", "C27", "C28", "C29", "C32", "C33"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query in the supplied cards; M04's source context suggests rifampicin but its SMILES is rifamycin SV, creating ambiguity.",
    "No matched oral-versus-IV comparator for the query or a close analog in L3.",
    "Rifabutin exposure records are not absolute F and C26 involves coadministration with saquinavir-ritonavir.",
    "C25/C31 are midazolam Tmax values, not rifaximin exposure.",
    "The physicochemical prior is descriptor-based only and does not account for rifamycin-class absorption mechanisms."
  ],
  "decision_summary": "Prediction remains high. L3 adds oral-exposure records for rifamycin analogs showing substantial systemic exposure after oral dosing, and none provides affirmative evidence of F < 20%. The low physicochemical prior is insufficient to override this class-level positive exposure evidence, so confidence increases to moderate."
}

